/* Boot identity is persistent; network reachability is checked independently of
 * passive robot telemetry. No notification is generated by restarting the agent. */
static const char *tg_boot_file="/proc/sys/kernel/random/boot_id";
static cJSON *tg_system_state;
static long tg_probe_next,tg_probe_bad_since;
static bool tg_probe_bad;
static bool tg_notice(const char *text);
static long tg_monotonic(void){struct timespec t;if(clock_gettime(CLOCK_MONOTONIC,&t))return 0;return t.tv_sec;}
static bool tg_system_enabled(void){return cJSON_IsTrue(get(tg_config,"enabled"))&&cJSON_IsTrue(get(tg_config,"system"))&&*str(tg_config,"chat_id","");}
static bool tg_system_save(void){char p[1024];path(p,sizeof p,"telegram-system.json");char *json=cJSON_PrintUnformatted(tg_system_state);bool ok=json&&atomic_write(p,json);free(json);return ok;}
static bool tg_boot_valid(const char *s){
 if(strlen(s)!=36)return false;
 for(int i=0;i<36;i++){if(i==8||i==13||i==18||i==23){if(s[i]!='-')return false;}else if(!isxdigit((unsigned char)s[i]))return false;}return true;
}
static void tg_system_init(void){
 if(tg_system_state||!strcmp(mode,"demo"))return;
 char *boot=read_file(tg_boot_file,64);if(!boot)return;boot[strcspn(boot,"\r\n")]=0;if(!tg_boot_valid(boot)){free(boot);return;}
 char p[1024];path(p,sizeof p,"telegram-system.json");tg_system_state=tg_read(p,4096);
 if(!cJSON_IsObject(tg_system_state)){cJSON_Delete(tg_system_state);tg_system_state=cJSON_CreateObject();}
 const char *old=str(tg_system_state,"boot_id","");bool existed=tg_boot_valid(old),changed=strcmp(old,boot)!=0;
 if(changed){
  setstr(tg_system_state,"boot_id",boot);setbool(tg_system_state,"reboot_pending",existed&&tg_system_enabled());
  setbool(tg_system_state,"outage",false);
  /* First install is only a baseline, not a reboot or an Internet event. */
  if(!tg_system_save()){cJSON_Delete(tg_system_state);tg_system_state=NULL;snprintf(tg_result,sizeof tg_result,"Could not save restart notification state");}
 }
 free(boot);
}
static void tg_system_config_changed(bool destination_changed){
 tg_probe_bad=false;tg_probe_bad_since=0;tg_probe_next=0;
 if(!tg_system_state)return;
 if(destination_changed||!tg_system_enabled()){
  bool dirty=cJSON_IsTrue(get(tg_system_state,"reboot_pending"))||cJSON_IsTrue(get(tg_system_state,"outage"));
  setbool(tg_system_state,"reboot_pending",false);setbool(tg_system_state,"outage",false);
  if(dirty)tg_system_save();
 }
}
static void tg_system_result(bool online,bool network_failure,long now){
 tg_probe_next=now+120;
 if(!tg_system_enabled()||!tg_system_state)return;
 if(!online){
  if(!network_failure){tg_probe_bad=false;tg_probe_bad_since=0;return;} // credential/API/clock failures do not prove an outage
  if(!tg_probe_bad){tg_probe_bad=true;tg_probe_bad_since=now;}
  if(now-tg_probe_bad_since>=120&&!cJSON_IsTrue(get(tg_system_state,"outage"))){setbool(tg_system_state,"outage",true);tg_system_save();}
  return;
 }
 tg_probe_bad=false;tg_probe_bad_since=0;
 bool reboot=cJSON_IsTrue(get(tg_system_state,"reboot_pending")),restored=cJSON_IsTrue(get(tg_system_state,"outage"));
 if(!reboot&&!restored)return;
 /* Record before enqueueing: no repeated startup message after an agent restart.
  * Like the RAM queue, a crash here may lose a notification rather than replay it. */
 setbool(tg_system_state,"reboot_pending",false);setbool(tg_system_state,"outage",false);
 if(!tg_system_save()){setbool(tg_system_state,"reboot_pending",reboot);setbool(tg_system_state,"outage",restored);return;}
 tg_notice(reboot?"Robot restarted\nInternet connection available · Telegram reachable":"Internet connection restored · Telegram reachable");
}
static bool tg_network_failure(int rc){return rc==5||rc==6||rc==7||rc==28||rc==35||rc==55||rc==56;}
